package com.farika.soundflow;
import android.app.*;import android.content.*;import android.media.AudioManager;import android.os.*;import java.util.*;
final class ContinuityCases {
 static void run(Instrumentation t){ResumeCases r=new ResumeCases(t);Context c=t.getTargetContext();try{r.fixture();Activity a=r.launch();r.play();r.main(()->{PlaybackService.instance.seek(12000);PlaybackService.instance.repeat=true;PlaybackService.instance.checkpoint();});r.waitReady();r.waitPlaying(true);PlaybackCheckpoint.Snapshot saved=PlaybackCheckpoint.read(c);r.check(saved.wanted&&!saved.suspended&&saved.savedAt>0,"active_resume_intent_durable");r.main(a::finish);Thread.sleep(600);r.check(r.actual(),"activity_destroy_does_not_stop_audio");r.main(()->PlaybackService.instance.onTaskRemoved(new Intent()));r.check(r.actual(),"task_removed_keeps_audio");
 r.stop();r.check(!PlaybackCheckpoint.read(c).wanted,"explicit_stop_clears_restart_autoplay");PlaybackCheckpoint.save(c,saved.queue,saved.index,12000,false,true,true,false);c.startForegroundService(new Intent(c,PlaybackService.class).setAction("SYSTEM_RESTORE"));r.waitReady();r.waitPlaying(true);r.check(r.actual(),"recent_system_restart_continues_audio");r.check(PlaybackCheckpoint.read(c).queue.equals(saved.queue),"system_restart_preserves_full_queue");
 r.main(()->PlaybackService.instance.pause());r.check(!PlaybackCheckpoint.read(c).wanted,"pause_persists_no_autoplay");r.stop();c.startForegroundService(new Intent(c,PlaybackService.class).setAction("SYSTEM_RESTORE"));r.waitReady();r.check(!r.actual(),"paused_system_restart_stays_paused");r.stop();PlaybackCheckpoint.save(c,saved.queue,saved.index,12000,false,true,true,true);c.startForegroundService(new Intent(c,PlaybackService.class).setAction("SYSTEM_RESTORE"));r.waitReady();r.check(!r.actual(),"suspended_system_restart_stays_paused");r.stop();
 c.getSharedPreferences("playback_settings",0).edit().putBoolean("system_resume",false).commit();PlaybackCheckpoint.save(c,saved.queue,saved.index,12000,false,true,true,false);c.startForegroundService(new Intent(c,PlaybackService.class).setAction("SYSTEM_RESTORE"));r.waitReady();r.check(!r.actual(),"disabled_restart_resume_stays_paused");r.stop();c.getSharedPreferences("playback_settings",0).edit().putBoolean("system_resume",true).commit();
 // Stale Activity bundle from another process must not reopen a stale tab.
 Activity main=r.launch();Bundle old=new Bundle();old.putString("process","different-process");old.putString("page","search");r.main(main::finish);Thread.sleep(300);Intent next=new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);Activity fresh=t.startActivitySync(next);r.check("home".equals(MotionCases.field(fresh,"page")),"fresh_activity_starts_home");r.check(PlaybackCheckpoint.read(c)!=null,"ui_reset_keeps_music_checkpoint");r.main(fresh::finish);r.out.putInt("checks",r.n);t.finish(Activity.RESULT_OK,r.out);
 }catch(Throwable e){r.out.putString("failure",e.getClass().getSimpleName()+": "+e.getMessage());t.finish(Activity.RESULT_CANCELED,r.out);}finally{try{r.stop();}catch(Exception ignored){}}}
}
